        /// <summary>Gets the borrowed complete catalog, excluding the no-format and count sentinels.</summary>
        [NativeBorrowedReturn]
        public static SwitchTextureFormat[] Formats => NativeFormats;
        /// <summary>Resolves an exact platform format identifier.</summary>
        public static bool TryGetFormat(string id, out SwitchTextureFormat format) {
            for (int index = 0; index < NativeFormats.Length; index++) if (NativeFormats[index].Id == id) { format = NativeFormats[index]; return true; }
            format = null; return false;
        }
        /// <summary>Resolves a bounded serialized deko3d format and native layout selection.</summary>
        [NativeBorrowedReturn]
        public static SwitchTextureFormat GetFormat(int code, bool blockLinear) {
            for (int index = 0; index < NativeFormats.Length; index++) if (NativeFormats[index].Code == code && NativeFormats[index].BlockLinear == blockLinear) return NativeFormats[index];
            throw new ArgumentException("Unknown Switch texture format.");
        }
